-- ============================================================
-- Portuguese Local Elections - Municipal Chamber Schema
-- ============================================================

BEGIN;

DROP TABLE IF EXISTS public.coalition_parties CASCADE;
DROP TABLE IF EXISTS public.party_candidacies CASCADE;
DROP TABLE IF EXISTS public.coalition_candidacies CASCADE;
DROP TABLE IF EXISTS public.citizen_group_candidacies CASCADE;
DROP TABLE IF EXISTS public.turnout CASCADE;
DROP TABLE IF EXISTS public.municipalities CASCADE;
DROP TABLE IF EXISTS public.districts CASCADE;
DROP TABLE IF EXISTS public.elections CASCADE;
DROP TABLE IF EXISTS public.parties CASCADE;

-- ============================================================
-- Elections
-- ============================================================

CREATE SCHEMA IF NOT EXISTS public;


CREATE TABLE public.elections (
    election_year    INTEGER PRIMARY KEY,
    election_date    DATE,
    description      TEXT,
    created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP

);

-- ============================================================
-- Territory
-- ============================================================

CREATE TABLE public.districts (
    id    INTEGER PRIMARY KEY, --code  VARCHAR(6) PRIMARY KEY,
    name  TEXT NOT NULL,
    type  TEXT NOT NULL
);

CREATE TABLE public.municipalities (
    code            VARCHAR(6) PRIMARY KEY,
    district        INTEGER NOT NULL REFERENCES districts(id)
                                ON UPDATE CASCADE ON DELETE RESTRICT,
    name            TEXT NOT NULL
);

-- ============================================================
-- Turnout and available mandates
-- ============================================================

CREATE TABLE public.turnout (
    election_year       INTEGER NOT NULL REFERENCES elections(election_year)
                                ON UPDATE CASCADE ON DELETE RESTRICT,
    municipality_code   VARCHAR(6) NOT NULL REFERENCES municipalities(code)
                                    ON UPDATE CASCADE ON DELETE RESTRICT,
    registered_voters  INTEGER NOT NULL DEFAULT 0,
    voters             INTEGER NOT NULL DEFAULT 0,
    blank_votes        INTEGER NOT NULL DEFAULT 0,
    null_votes         INTEGER NOT NULL DEFAULT 0,
    total_mandates     INTEGER NOT NULL,

    PRIMARY KEY (election_year, municipality_code),

    CONSTRAINT ck_turnout_non_negative CHECK (
        registered_voters >= 0
        AND voters >= 0
        AND blank_votes >= 0
        AND null_votes >= 0
    ),
    CONSTRAINT ck_turnout_voters_lte_registered CHECK (voters <= registered_voters),
    CONSTRAINT ck_turnout_blank_null_lte_voters CHECK ((blank_votes + null_votes) <= voters),
    CONSTRAINT ck_turnout_total_mandates_positive CHECK (total_mandates > 0)
);


-- ============================================================
-- Political entities
-- ============================================================

CREATE TABLE public.parties (
    party_id SERIAL PRIMARY KEY,
    acronym  TEXT NOT NULL, 
    name     TEXT NOT NULL,
    logo_url TEXT NOT NULL,
    active   BOOLEAN NOT NULL DEFAULT TRUE
);

-- ============================================================
-- Candidacies with votes and Mandate allocations
-- ============================================================


CREATE TABLE public.party_candidacies (
    election_year       INTEGER NOT NULL,
    municipality_code   VARCHAR(6) NOT NULL,
    party_id            INTEGER NOT NULL REFERENCES parties(party_id)
                                ON UPDATE CASCADE ON DELETE RESTRICT,
    votes               INTEGER NOT NULL DEFAULT 0,
    calculated_mandates INTEGER NOT NULL DEFAULT 0,
    expected_mandates   INTEGER NOT NULL DEFAULT 0,

    PRIMARY KEY (election_year, municipality_code, party_id),

    FOREIGN KEY (election_year, municipality_code)
        REFERENCES turnout(election_year, municipality_code)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_party_candidacies_votes_non_negative CHECK (votes >= 0),
    CONSTRAINT ck_party_mandates_calculated_non_negative CHECK (calculated_mandates >= 0),
    CONSTRAINT ck_party_mandates_expected_non_negative CHECK (expected_mandates >= 0)
);

CREATE TABLE public.coalition_candidacies (
    election_year       INTEGER NOT NULL,
    municipality_code   VARCHAR(6) NOT NULL,
    acronym             TEXT NOT NULL,
    name                TEXT NOT NULL,
    votes               INTEGER NOT NULL DEFAULT 0,
    calculated_mandates INTEGER NOT NULL DEFAULT 0,
    expected_mandates   INTEGER NOT NULL DEFAULT 0,

    PRIMARY KEY (election_year, municipality_code, acronym),

    FOREIGN KEY (election_year, municipality_code)
        REFERENCES turnout(election_year, municipality_code)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    
    CONSTRAINT ck_coalition_candidacies_votes_non_negative CHECK (votes >= 0),
    CONSTRAINT ck_coalition_mandates_calculated_non_negative CHECK (calculated_mandates >= 0),
    CONSTRAINT ck_colaition_mandates_expected_non_negative CHECK (expected_mandates >= 0)
);

CREATE TABLE public.citizen_group_candidacies (
    election_year       INTEGER NOT NULL,
    municipality_code   VARCHAR(6) NOT NULL,
    acronym             TEXT NOT NULL,
    name                TEXT NOT NULL,
    votes               INTEGER NOT NULL DEFAULT 0,
    calculated_mandates INTEGER NOT NULL DEFAULT 0,
    expected_mandates   INTEGER NOT NULL DEFAULT 0,

    PRIMARY KEY (election_year, municipality_code, acronym),

    FOREIGN KEY (election_year, municipality_code)
        REFERENCES turnout(election_year, municipality_code)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    
    CONSTRAINT ck_citizen_group_candidacies_votes_non_negative CHECK (votes >= 0),
    CONSTRAINT ck_citizen_group_mandates_calculated_non_negative CHECK (calculated_mandates >= 0),
    CONSTRAINT ck_citizen_group_mandates_expected_non_negative CHECK (expected_mandates >= 0)
);

CREATE TABLE public.coalition_parties (
    election_year       INTEGER NOT NULL,
    municipality_code   VARCHAR(6) NOT NULL,
    coalition_acronym   TEXT NOT NULL,
    order_number        INTEGER NOT NULL,
    party_id            INTEGER NOT NULL REFERENCES parties(party_id)
                                ON UPDATE CASCADE ON DELETE RESTRICT,

    PRIMARY KEY (election_year, municipality_code, coalition_acronym, order_number),

    FOREIGN KEY (election_year, municipality_code, coalition_acronym)
        REFERENCES coalition_candidacies(election_year, municipality_code, acronym)
        ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE INDEX idx_municipalities_district ON municipalities(district);

CREATE SCHEMA IF NOT EXISTS geo;
CREATE EXTENSION IF NOT EXISTS POSTGIS;


